mapper.select:
SELECT 
FROM task_template_version
WHERE deleted = 0
  AND task_template_code = #{taskTemplateCode}
  AND version = #{version}
LIMIT 1

mapper.update:
UPDATE task_template_version
SET status = #{status}
WHERE deleted = 0
  AND task_template_code = #{taskTemplateCode}
  AND version = #{version}

UPDATE task_template_version
SET status = 'EXPIRED'
WHERE deleted = 0
  AND task_template_code = #{taskTemplateCode}
  AND version <> #{excludeVersion}
  AND status <> 'EXPIRED'
